  "输入 Web Token，验证网关访问权限。": ["Enter your Web Token to access the gateway.", "Introduce tu Web Token para acceder a la puerta de enlace.", "Saisissez votre Web Token pour accéder à la passerelle.", "Geben Sie Ihren Web Token für den Gateway-Zugriff ein.", "Insira seu Web Token para acessar o gateway.", "Введите Web Token для доступа к шлюзу.", "Web Token を入力してゲートウェイへのアクセスを認証します。", "Web Token을 입력하여 게이트웨이 접근 권한을 확인하세요."],
