  "应用上游声明": ["Apply upstream declaration", "Aplicar declaración del proveedor", "Appliquer la déclaration en amont", "Upstream-Deklaration anwenden", "Aplicar declaração do provedor", "Применить заявление вышестоящего сервиса", "上流の能力宣言を適用", "상위 서비스 선언 적용"],
  "此协议直接读取上游能力声明，登记和探测不会生成内容；测试模型会发送真实请求。": ["This protocol reads upstream capability declarations. Registration and probing do not generate content; model tests send real requests.", "Este protocolo lee las capacidades declaradas. El registro y la detección no generan contenido; las pruebas envían solicitudes reales.", "Ce protocole lit les capacités déclarées en amont. L’enregistrement et la détection ne génèrent aucun contenu ; les tests envoient des requêtes réelles.", "Dieses Protokoll liest die deklarierten Upstream-Fähigkeiten. Registrierung und Erkennung erzeugen keine Inhalte; Modelltests senden echte Anfragen.", "Este protocolo lê as capacidades declaradas pelo provedor. Registro e detecção não geram conteúdo; testes enviam solicitações reais.", "Протокол читает заявленные возможности сервиса. Регистрация и проверка возможностей не создают контент; тест модели отправляет настоящий запрос.", "このプロトコルは上流の能力宣言を読み取ります。登録と能力取得では生成せず、モデルテストでは実際のリクエストを送信します。", "이 프로토콜은 상위 서비스의 기능 선언을 읽습니다. 등록과 기능 조회는 콘텐츠를 생성하지 않으며 모델 테스트는 실제 요청을 보냅니다."],
  "文件生成": ["File generation", "Generación de archivos", "Génération de fichiers", "Dateierzeugung", "Geração de arquivos", "Генерация файлов", "ファイル生成", "파일 생성"],
  "媒体模型会实际生成音频、视频或文件，探测可能产生费用。": ["Media models generate real audio, videos or files during probing, which may incur charges.", "Los modelos multimedia generan audio, vídeos o archivos reales durante las pruebas, lo que puede generar cargos.", "Les modèles multimédias génèrent réellement de l’audio, des vidéos ou des fichiers pendant les tests, ce qui peut être facturé.", "Medienmodelle erzeugen bei der Prüfung echtes Audio, Videos oder Dateien. Dabei können Kosten entstehen.", "Modelos de mídia geram áudio, vídeos ou arquivos reais durante a verificação, o que pode gerar custos.", "При проверке медиамодели создают настоящее аудио, видео или файлы, что может быть платным.", "メディアモデルの検証では音声・動画・ファイルを実際に生成し、料金が発生する場合があります。", "미디어 모델 검사 시 실제 오디오, 비디오 또는 파일이 생성되며 비용이 발생할 수 있습니다."],
  "未验证的模板参考": ["Unverified template references", "Referencias de plantilla sin verificar", "Références de modèle non vérifiées", "Ungeprüfte Vorlagenreferenzen", "Referências de modelo não verificadas", "Непроверенные модели из шаблона", "未検証のテンプレート参照", "검증되지 않은 템플릿 참조"],
