  "替换同名用户资源（需先停用）": ["Replace user resource with the same ID (disable it first)", "Sustituir recurso de usuario con el mismo ID (desactivar primero)", "Remplacer la ressource utilisateur de même ID (désactiver d’abord)", "Benutzerressource mit gleicher ID ersetzen (zuerst deaktivieren)", "Substituir recurso do usuário com o mesmo ID (desative primeiro)", "Заменить ресурс пользователя с тем же ID (сначала отключите)", "同じ ID のユーザーリソースを置換（先に無効化）", "동일 ID의 사용자 리소스 교체 (먼저 비활성화)"],
  "内置资源随更新覆盖；用户资源独立保存，更新时保留。": ["Updates replace built-in resources and preserve user resources.", "Las actualizaciones sustituyen los recursos integrados y conservan los del usuario.", "Les mises à jour remplacent les ressources intégrées et conservent celles des utilisateurs.", "Updates ersetzen integrierte Ressourcen und erhalten Benutzerressourcen.", "As atualizações substituem os recursos integrados e preservam os do usuário.", "Обновления заменяют встроенные ресурсы и сохраняют пользовательские.", "更新時は内蔵リソースを置換し、ユーザーリソースを保持します。", "업데이트 시 내장 리소스를 교체하고 사용자 리소스를 보존합니다."],
  "内置资源已更新，请重启网关生效。": ["Built-in resources updated. Restart the gateway to apply them.", "Recursos integrados actualizados. Reinicia la puerta de enlace para aplicarlos.", "Ressources intégrées mises à jour. Redémarrez la passerelle pour les appliquer.", "Integrierte Ressourcen aktualisiert. Gateway zum Anwenden neu starten.", "Recursos integrados atualizados. Reinicie o gateway para aplicar.", "Встроенные ресурсы обновлены. Перезапустите шлюз для применения.", "内蔵リソースを更新しました。反映にはゲートウェイの再起動が必要です。", "내장 리소스가 업데이트되었습니다. 적용하려면 게이트웨이를 다시 시작하세요."],
  "内置资源更新": ["Built-in resource updates", "Actualizaciones de recursos integrados", "Mises à jour des ressources intégrées", "Updates integrierter Ressourcen", "Atualizações de recursos integrados", "Обновление встроенных ресурсов", "内蔵リソースの更新", "내장 리소스 업데이트"],
  "仅更新内置适配器和模板，框架版本、用户资源和运行数据保持不变。": ["Only built-in adapters and templates are updated. Framework version, user resources and runtime data are preserved.", "Solo se actualizan adaptadores y plantillas integrados. Se conservan la versión del marco, los recursos del usuario y los datos.", "Seuls les adaptateurs et modèles intégrés sont mis à jour. Version du framework, ressources utilisateur et données sont conservées.", "Nur integrierte Adapter und Vorlagen werden aktualisiert. Framework-Version, Benutzerressourcen und Laufzeitdaten bleiben erhalten.", "Somente adaptadores e modelos integrados são atualizados. A versão do framework, os recursos do usuário e os dados são preservados.", "Обновляются только встроенные адаптеры и шаблоны. Версия платформы, пользовательские ресурсы и данные сохраняются.", "内蔵アダプターとテンプレートのみ更新します。フレームワークのバージョン、ユーザーリソース、実行データは保持されます。", "내장 어댑터와 템플릿만 업데이트합니다. 프레임워크 버전, 사용자 리소스 및 실행 데이터는 보존됩니다."],
  "更新内置资源": ["Update built-in resources", "Actualizar recursos integrados", "Mettre à jour les ressources intégrées", "Integrierte Ressourcen aktualisieren", "Atualizar recursos integrados", "Обновить встроенные ресурсы", "内蔵リソースを更新", "내장 리소스 업데이트"],
  "模型目录可能不完整；可手动填写准确模型 ID，登记时会实际探测。": ["The model list may be incomplete. Enter an exact model ID manually; registration will probe it.", "La lista de modelos puede estar incompleta. Introduce el ID exacto; se probará al registrarlo.", "La liste des modèles peut être incomplète. Saisissez l’ID exact ; il sera testé à l’enregistrement.", "Die Modellliste kann unvollständig sein. Exakte Modell-ID manuell eingeben; sie wird bei der Registrierung geprüft.", "A lista de modelos pode estar incompleta. Digite o ID exato; ele será testado no registro.", "Каталог моделей может быть неполным. Введите точный ID вручную; при регистрации будет выполнена проверка.", "モデル一覧は不完全な場合があります。正確なモデル ID を手入力すると、登録時に実際に検証されます。", "모델 목록이 불완전할 수 있습니다. 정확한 모델 ID를 직접 입력하면 등록 시 실제로 검사합니다."],
