  "查看网关概况与按天、按小时汇总的请求趋势。": ["View gateway activity and daily or hourly request trends.", "Consulta la actividad de la puerta de enlace y las tendencias diarias u horarias.", "Consultez l’activité de la passerelle et les tendances quotidiennes ou horaires.", "Gateway-Aktivität und tägliche oder stündliche Anfragetrends anzeigen.", "Veja a atividade do gateway e tendências diárias ou por hora.", "Обзор шлюза и динамика запросов по дням и часам.", "ゲートウェイの概要と日別・時間別のリクエスト傾向を確認します。", "게이트웨이 개요와 일별·시간별 요청 추세를 확인합니다."],
