  "界面偏好仅保存在当前浏览器，不影响其他用户。": ["Preferences apply to this browser and do not affect other users.", "Las preferencias se guardan en este navegador y no afectan a otros usuarios.", "Les préférences concernent ce navigateur et n’affectent pas les autres utilisateurs.", "Einstellungen gelten für diesen Browser und beeinflussen keine anderen Nutzer.", "As preferências valem para este navegador e não afetam outros usuários.", "Настройки сохраняются в этом браузере и не влияют на других пользователей.", "設定はこのブラウザーに保存され、他のユーザーには影響しません。", "환경설정은 현재 브라우저에 저장되며 다른 사용자에게 영향을 주지 않습니다."],
  "控制接口开关、重试次数与失败冷却。": ["Manage API access, retry attempts and failure cooldown.", "Configura el acceso a la API, los intentos y la pausa tras fallos.", "Gérez l’accès à l’API, les tentatives et le délai après échec.", "API-Zugriff, Wiederholungsversuche und Wartezeit nach Fehlern verwalten.", "Gerencie acesso à API, tentativas e intervalo após falhas.", "Доступ к API, число попыток и пауза после ошибок.", "API の有効化、試行回数、失敗後の待機時間を管理します。", "API 사용 여부, 재시도 횟수와 실패 후 대기 시간을 관리합니다."],
  "控制下游 API 是否接受请求。": ["Allow or pause downstream API requests.", "Permite o pausa las solicitudes de clientes a la API.", "Autorisez ou suspendez les requêtes des clients.", "Anfragen nachgelagerter Clients erlauben oder pausieren.", "Permita ou pause solicitações de clientes à API.", "Разрешить или приостановить запросы клиентов к API.", "下流 API リクエストの受け付けを切り替えます。", "다운스트림 API 요청 수신 여부를 설정합니다."],
  "仅保存本组配置。": ["Saves this section only.", "Solo se guarda esta sección.", "Enregistre uniquement cette rubrique.", "Speichert nur diesen Bereich.", "Salva apenas esta seção.", "Сохраняется только этот раздел.", "このグループの設定だけを保存します。", "이 그룹의 설정만 저장합니다."],
