  "导出上游、模型和路由目录，敏感信息自动脱敏。": ["Export the upstream, model and routing catalog with secrets redacted.", "Exporta el catálogo de proveedores, modelos y rutas con los secretos ocultos.", "Exportez le catalogue des fournisseurs, modèles et routes avec les secrets masqués.", "Anbieter-, Modell- und Routingkatalog mit ausgeblendeten Geheimnissen exportieren.", "Exporte o catálogo de provedores, modelos e rotas com segredos ocultos.", "Экспорт каталога провайдеров, моделей и маршрутов с удалением секретов.", "上流、モデル、ルートの一覧をエクスポートします。秘密情報はマスクされます。", "업스트림, 모델, 라우팅 목록을 내보내며 민감한 정보는 마스킹합니다."],
  "启动配置": ["Startup configuration", "Configuración de inicio", "Configuration de démarrage", "Startkonfiguration", "Configuração de inicialização", "Настройки запуска", "起動設定", "시작 설정"],
  "编辑启动参数，保存后重启网关生效。": ["Edit startup parameters, save, then restart to apply.", "Edita los parámetros de inicio, guarda y reinicia para aplicarlos.", "Modifiez les paramètres, enregistrez puis redémarrez pour les appliquer.", "Startparameter bearbeiten, speichern und zum Anwenden neu starten.", "Edite os parâmetros, salve e reinicie para aplicar.", "Измените параметры, сохраните и перезапустите шлюз.", "起動パラメーターを編集し、保存後に再起動すると反映されます。", "시작 매개변수를 편집하고 저장한 후 재시작하면 적용됩니다."],
  "保存后到系统维护重启网关。": ["After saving, restart from System maintenance.", "Tras guardar, reinicia desde Mantenimiento del sistema.", "Après enregistrement, redémarrez depuis Maintenance système.", "Nach dem Speichern unter Systemwartung neu starten.", "Após salvar, reinicie em Manutenção do sistema.", "После сохранения перезапустите в разделе обслуживания.", "保存後、システム保守からゲートウェイを再起動してください。", "저장한 후 시스템 유지 관리에서 재시작하세요."],
  "全局指令": ["Global instructions", "Instrucciones globales", "Instructions globales", "Globale Anweisungen", "Instruções globais", "Глобальные инструкции", "グローバル指示", "전역 지침"],
