  "查看运行状态，在请求结束后加载已保存的配置。": ["Review process status and apply saved settings after active requests finish.", "Consulta el estado y aplica lo guardado al terminar las solicitudes activas.", "Consultez l’état et appliquez les paramètres après la fin des requêtes actives.", "Status prüfen und gespeicherte Einstellungen nach laufenden Anfragen laden.", "Confira o estado e aplique configurações após as solicitações ativas terminarem.", "Проверка состояния и загрузка настроек после завершения активных запросов.", "稼働状態を確認し、実行中のリクエスト完了後に保存済みの設定を読み込みます。", "실행 상태를 확인하고 진행 중인 요청이 끝난 후 저장된 설정을 불러옵니다."],
