  "查看当前版本与远程更新。": ["View the installed version and check for updates.", "Consulta la versión instalada y busca actualizaciones.", "Consultez la version installée et recherchez des mises à jour.", "Installierte Version anzeigen und nach Updates suchen.", "Veja a versão instalada e verifique atualizações.", "Текущая версия и проверка обновлений.", "現在のバージョンと更新を確認します。", "설치된 버전과 업데이트를 확인합니다."],
