  "以下配置由进程环境覆盖": ["Process environment overrides these settings", "El entorno del proceso sustituye estos ajustes", "L’environnement du processus remplace ces paramètres", "Prozessvariablen überschreiben diese Einstellungen", "O ambiente do processo substitui estas configurações", "Эти настройки переопределены окружением процесса", "次の設定はプロセスの環境変数で上書きされます", "프로세스 환경이 다음 설정을 재정의합니다"],
