  "勾选后才替换该项；留空并保存表示清除。密钥原文不会回显。": ["Select a field to replace it. Saving an empty value clears it. Plaintext secrets are never returned.", "Marca un campo para sustituirlo. Guardarlo vacío lo borra. Los secretos nunca se muestran en texto plano.", "Cochez un champ pour le remplacer. Une valeur vide l’efface. Les secrets ne sont jamais affichés en clair.", "Feld zum Ersetzen auswählen. Ein leerer Wert löscht es. Geheimnisse werden nie im Klartext angezeigt.", "Marque um campo para substituí-lo. Salvar vazio o apaga. Segredos nunca são exibidos em texto simples.", "Отметьте поле для замены. Пустое значение очищает его. Секреты не возвращаются открытым текстом.", "チェックした項目だけ置き換えます。空欄で保存すると消去します。秘密情報の原文は表示しません。", "선택한 항목만 바꿉니다. 빈 값으로 저장하면 삭제됩니다. 비밀 값의 원문은 표시하지 않습니다."],
  "启动命令": ["Startup command", "Comando de inicio", "Commande de démarrage", "Startbefehl", "Comando de inicialização", "Команда запуска", "起動コマンド", "시작 명령"],
