  "启动配置仅所有者可编辑。": ["Only the owner can edit startup configuration.", "Solo el propietario puede editar la configuración de inicio.", "Seul le propriétaire peut modifier la configuration de démarrage.", "Nur der Eigentümer kann die Startkonfiguration bearbeiten.", "Somente o proprietário pode editar a configuração de inicialização.", "Настройки запуска может изменять только владелец.", "起動設定は所有者のみ編集できます。", "소유자만 시작 설정을 편집할 수 있습니다."],
  "启动配置已保存，请到系统维护重启网关。": ["Startup configuration saved. Restart the gateway in System maintenance.", "Configuración guardada. Reinicia la puerta de enlace en Mantenimiento del sistema.", "Configuration enregistrée. Redémarrez la passerelle dans Maintenance système.", "Startkonfiguration gespeichert. Gateway unter Systemwartung neu starten.", "Configuração salva. Reinicie o gateway em Manutenção do sistema.", "Настройки сохранены. Перезапустите шлюз в разделе обслуживания.", "起動設定を保存しました。システム管理でゲートウェイを再起動してください。", "시작 설정을 저장했습니다. 시스템 유지 관리에서 게이트웨이를 다시 시작하세요."],
  "实时接收": ["Receiving live", "Recepción en directo", "Réception en direct", "Live-Empfang", "Recebendo ao vivo", "Приём в реальном времени", "受信中", "실시간 수신 중"],
  "已完成": ["Finished", "Finalizadas", "Terminés", "Abgeschlossen", "Concluídas", "Завершено", "完了", "완료"],
