  "平均首字延迟": ["Mean time to first token", "Latencia media del primer token", "Délai moyen du premier token", "Mittlere Zeit bis zum ersten Token", "Latência média do primeiro token", "Среднее время до первого токена", "最初のトークンまでの平均時間", "평균 첫 토큰 지연"],
  "成本总计": ["Total cost", "Coste total", "Coût total", "Gesamtkosten", "Custo total", "Общая стоимость", "合計料金", "총 비용"],
  "成本金额种类显示": ["Cost display currency", "Moneda de los costes", "Devise d’affichage des coûts", "Anzeigewährung für Kosten", "Moeda de exibição dos custos", "Валюта отображения стоимости", "料金の表示通貨", "비용 표시 통화"],
  "使用固定汇率（{date}）换算，仅影响金额显示。": ["Uses fixed exchange rates ({date}); affects displayed amounts only.", "Usa tipos de cambio fijos ({date}); solo afecta a los importes mostrados.", "Utilise des taux fixes ({date}) ; seuls les montants affichés changent.", "Verwendet feste Wechselkurse ({date}); betrifft nur angezeigte Beträge.", "Usa taxas fixas ({date}); afeta apenas os valores exibidos.", "Используются фиксированные курсы ({date}); меняется только отображение сумм.", "固定為替レート（{date}）で換算し、金額の表示だけを変更します。", "고정 환율({date})로 환산하며 표시 금액에만 영향을 줍니다."],
  "汇率未配置": ["Exchange rate not configured", "Tipo de cambio no configurado", "Taux de change non configuré", "Wechselkurs nicht konfiguriert", "Taxa de câmbio não configurada", "Курс обмена не задан", "為替レート未設定", "환율이 설정되지 않음"],
  "按已知输入 Token 加权": ["Weighted by known input tokens", "Ponderada por tokens de entrada conocidos", "Pondéré par les tokens d’entrée connus", "Nach bekannten Eingabe-Tokens gewichtet", "Ponderada pelos tokens de entrada conhecidos", "Взвешено по известным входным токенам", "判明した入力トークン数で加重", "확인된 입력 토큰 기준 가중 평균"],
  "按真实上游调用统计，重试分别计数；不包含模型测试和能力探测。未知用量与价格保留未知。": ["Counts upstream attempts, including each retry. Model tests and capability probes are excluded. Unknown usage and prices remain unknown.", "Cuenta intentos al proveedor, incluido cada reintento. Excluye pruebas y sondeos. El uso y los precios desconocidos se mantienen como tales.", "Compte chaque tentative amont, y compris les relances. Tests et vérifications sont exclus. Usage et prix inconnus restent inconnus.", "Zählt jeden Upstream-Versuch einschließlich Wiederholungen. Modelltests und Fähigkeitsprüfungen sind ausgeschlossen. Unbekannte Nutzung und Preise bleiben unbekannt.", "Conta cada tentativa ao provedor, incluindo repetições. Testes e verificações são excluídos. Uso e preços desconhecidos permanecem desconhecidos.", "Учитываются попытки к провайдеру, включая повторы. Тесты и проверки возможностей исключены. Неизвестные расход и цены не подменяются.", "再試行を含む上流への呼び出しを集計します。モデルテストと機能検証は除外し、不明な使用量と料金は不明のまま保持します。", "재시도를 포함한 업스트림 호출을 집계합니다. 모델 테스트와 기능 탐지는 제외하며 알 수 없는 사용량과 가격은 그대로 유지합니다."],
  "排行维度": ["Ranking dimension", "Dimensión de clasificación", "Dimension du classement", "Ranglistendimension", "Dimensão do ranking", "Разрез рейтинга", "ランキングの区分", "순위 기준"],
  "数据范围": ["Data range", "Intervalo de datos", "Période des données", "Datenzeitraum", "Período dos dados", "Период данных", "集計期間", "데이터 범위"],
  "暂无终端输出": ["No terminal output yet", "Sin salida de terminal", "Aucune sortie du terminal", "Noch keine Terminalausgabe", "Sem saída do terminal", "Вывода терминала пока нет", "ターミナル出力はまだありません", "터미널 출력이 없습니다"],
