  "有可用更新": ["Update available", "Actualización disponible", "Mise à jour disponible", "Update verfügbar", "Atualização disponível", "Доступно обновление", "更新があります", "업데이트 있음"],
  "服务运行时可在此优雅重启；停止后需在源码目录执行启动命令。": ["Restart gracefully here while running. When stopped, run the startup command from the source directory.", "Puedes reiniciar aquí mientras está en ejecución. Si está detenido, ejecuta el comando en el directorio del código.", "Redémarrez proprement ici pendant l’exécution. À l’arrêt, lancez la commande depuis le répertoire source.", "Im laufenden Betrieb hier geordnet neu starten. Nach dem Stoppen den Startbefehl im Quellverzeichnis ausführen.", "Reinicie aqui enquanto estiver ativo. Quando parado, execute o comando no diretório do código.", "Работающий шлюз можно перезапустить здесь. После остановки выполните команду в каталоге исходников.", "稼働中はここで安全に再起動できます。停止中はソースディレクトリで起動コマンドを実行してください。", "실행 중에는 여기서 정상적으로 재시작할 수 있습니다. 중지된 경우 소스 디렉터리에서 시작 명령을 실행하세요."],
  "未关联密钥": ["No linked key", "Sin clave asociada", "Aucune clé associée", "Kein zugeordneter Schlüssel", "Sem chave associada", "Ключ не указан", "キー未設定", "연결된 키 없음"],
