  "查看调用统计、提供商与模型排行，以及当前进程的启动终端。": ["View call metrics, provider and model rankings, and the current process terminal.", "Consulta estadísticas, clasificaciones y el terminal del proceso actual.", "Consultez les statistiques, classements et le terminal du processus actuel.", "Aufrufstatistiken, Anbieter- und Modellranglisten sowie das Prozessterminal anzeigen.", "Veja estatísticas, rankings de provedores e modelos e o terminal do processo atual.", "Статистика вызовов, рейтинги провайдеров и моделей и терминал текущего процесса.", "呼び出し統計、プロバイダー・モデルのランキング、現在のプロセスの起動ログを表示します。", "호출 통계, 공급자와 모델 순위 및 현재 프로세스의 시작 터미널을 확인합니다."],
