  "全部类型": ["All types", "Todos los tipos", "Tous les types", "Alle Typen", "Todos os tipos", "Все типы", "すべての種類", "모든 유형"],
  "模型类型": ["Model type", "Tipo de modelo", "Type de modèle", "Modelltyp", "Tipo de modelo", "Тип модели", "モデル種別", "모델 유형"],
  "全部状态": ["All statuses", "Todos los estados", "Tous les états", "Alle Status", "Todos os estados", "Все состояния", "すべての状態", "모든 상태"],
  "按当前浏览器时区筛选": ["Times use your browser’s timezone", "Horas según la zona horaria del navegador", "Horaires dans le fuseau du navigateur", "Zeiten in der Zeitzone des Browsers", "Horários no fuso do navegador", "Время в часовом поясе браузера", "ブラウザーのタイムゾーンで絞り込み", "브라우저 시간대 기준"],
