  "查看调用详情": ["View call details", "Ver detalles de llamada", "Voir les détails de l’appel", "Aufrufdetails anzeigen", "Ver detalhes da chamada", "Подробнее о вызове", "呼び出し詳細を表示", "호출 상세 보기"],
  "总耗时": ["Total latency", "Latencia total", "Durée totale", "Gesamtdauer", "Latência total", "Общее время", "総所要時間", "총 소요 시간"],
  "计量来源": ["Metering source", "Origen de medición", "Source de mesure", "Messquelle", "Origem da medição", "Источник учёта", "計量元", "계량 출처"],
