  "当前快照与最近 100 条 Attempt；没有用量证据的费用保持未知。": ["Current snapshot and the latest 100 attempts. Costs without usage evidence remain unknown.", "Instantánea actual y los últimos 100 intentos. Sin evidencia de uso, el coste es desconocido.", "Instantané actuel et 100 dernières tentatives. Sans preuve d’usage, le coût reste inconnu.", "Aktueller Stand und die letzten 100 Versuche. Kosten ohne Nutzungsnachweis bleiben unbekannt.", "Estado atual e últimas 100 tentativas. Custos sem evidência de uso permanecem desconhecidos.", "Текущий снимок и последние 100 попыток. Без данных об использовании стоимость неизвестна.", "現在のスナップショットと直近100件の試行。使用量が不明な費用は未確定です。", "현재 스냅샷과 최근 시도 100건입니다. 사용량 근거가 없는 비용은 알 수 없음으로 표시합니다."],
  "管理上游": ["Manage upstreams", "Gestionar servicios", "Gérer les services", "Upstreams verwalten", "Gerenciar serviços", "Управление сервисами", "接続先を管理", "업스트림 관리"],
