  "添加第一个上游，或调整搜索条件": ["Add an upstream or adjust your search", "Añade un servicio o ajusta la búsqueda", "Ajoutez un service ou modifiez la recherche", "Upstream hinzufügen oder Suche ändern", "Adicione um serviço ou ajuste a busca", "Добавьте сервис или измените поиск", "接続先を追加するか検索条件を変更してください", "업스트림을 추가하거나 검색 조건을 변경하세요"],
  "最近调用": ["Recent calls", "Llamadas recientes", "Appels récents", "Letzte Aufrufe", "Chamadas recentes", "Последние вызовы", "最近の呼び出し", "최근 호출"],
  "查看全部": ["View all", "Ver todo", "Tout afficher", "Alle anzeigen", "Ver tudo", "Показать все", "すべて表示", "모두 보기"],
  "暂无调用记录": ["No calls yet", "Sin llamadas", "Aucun appel", "Noch keine Aufrufe", "Nenhuma chamada", "Вызовов пока нет", "呼び出し履歴はありません", "호출 기록 없음"],
  "运行时快照": ["Runtime snapshot", "Instantánea de ejecución", "Instantané d’exécution", "Laufzeit-Snapshot", "Estado de execução", "Снимок среды выполнения", "ランタイムスナップショット", "런타임 스냅샷"],
  "排空中的旧快照": ["Draining generations", "Generaciones en drenaje", "Générations en cours de vidage", "Auslaufende Generationen", "Gerações em esvaziamento", "Завершающиеся поколения", "処理完了待ちの旧世代", "처리 완료를 기다리는 이전 세대"],
  "网关版本": ["Gateway version", "Versión del gateway", "Version de la passerelle", "Gateway-Version", "Versão do gateway", "Версия шлюза", "ゲートウェイのバージョン", "게이트웨이 버전"],
  "运行状态": ["Runtime status", "Estado de ejecución", "État d’exécution", "Laufzeitstatus", "Estado de execução", "Состояние", "実行状態", "실행 상태"],
  "冷却中的 Deployment": ["Deployments in cooldown", "Deployments en espera", "Deployments en temporisation", "Deployments in Abkühlung", "Deployments em espera", "Deployments на паузе", "クールダウン中のDeployment", "대기 중인 Deployment"],
  "默认计量器及厂商预设待确认；缺失的 usage 不会估算为精确值。": ["Default tokenizer and vendor presets are pending. Missing usage is never reported as exact.", "Tokenizador y proveedores predeterminados pendientes. El uso ausente nunca se informa como exacto.", "Tokeniseur et fournisseurs prédéfinis à confirmer. Un usage absent n’est jamais déclaré exact.", "Standard-Tokenizer und Anbietervorgaben sind offen. Fehlende Nutzung gilt nie als exakt.", "Tokenizador padrão e provedores predefinidos pendentes. Uso ausente nunca é declarado exato.", "Токенизатор и набор провайдеров ещё не выбраны. Отсутствующие данные не считаются точными.", "既定のトークナイザーとベンダープリセットは未確定です。使用量不明を正確な値として扱いません。", "기본 토크나이저와 공급자 프리셋은 미정입니다. 누락된 사용량을 정확한 값으로 표시하지 않습니다."],
  "内置协议独立于厂商；自定义代码在独立 worker 进程中运行。": ["Built-in protocols are vendor independent. Custom adapters run in separate worker processes.", "Los protocolos integrados son independientes del proveedor. El código personalizado usa procesos separados.", "Les protocoles intégrés sont indépendants des fournisseurs. Le code personnalisé s’exécute dans des processus séparés.", "Integrierte Protokolle sind anbieterunabhängig. Eigener Code läuft in separaten Prozessen.", "Os protocolos integrados independem do provedor. Código personalizado roda em processos separados.", "Встроенные протоколы не зависят от провайдера. Пользовательский код работает в отдельных процессах.", "内蔵プロトコルはベンダーに依存しません。独自コードは別のworkerプロセスで動作します。", "내장 프로토콜은 공급자와 독립적입니다. 사용자 코드는 별도 worker 프로세스에서 실행됩니다."],
  "内置模板可直接用于添加上游；自定义模板通过 ZIP 安装。": ["Built-in templates are ready to use when adding an upstream. Install custom templates from ZIP files.", "Las plantillas integradas están listas para añadir servicios de origen. Instala plantillas personalizadas desde archivos ZIP.", "Les modèles intégrés sont prêts à créer un service amont. Installez les modèles personnalisés depuis un fichier ZIP.", "Integrierte Vorlagen stehen beim Hinzufügen eines Upstreams bereit. Eigene Vorlagen werden per ZIP installiert.", "Os modelos integrados podem ser usados ao adicionar um serviço de origem. Instale modelos personalizados por ZIP.", "Встроенные шаблоны доступны при добавлении сервиса. Пользовательские шаблоны устанавливаются из ZIP.", "接続先の追加時に内蔵テンプレートをそのまま利用できます。独自テンプレートはZIPからインストールします。", "업스트림을 추가할 때 내장 템플릿을 바로 사용할 수 있습니다. 사용자 정의 템플릿은 ZIP으로 설치합니다."],
  "选择模板后填写上游密钥；真实厂商能力仍需实测确认。": ["Select a template, then enter the upstream API key. Verify vendor capabilities with real calls.", "Selecciona una plantilla e introduce la clave API. Verifica las capacidades del proveedor con llamadas reales.", "Sélectionnez un modèle, puis saisissez la clé API. Vérifiez les capacités du fournisseur par des appels réels.", "Vorlage auswählen und den API-Schlüssel eingeben. Anbieterfähigkeiten müssen durch reale Aufrufe geprüft werden.", "Selecione um modelo e informe a chave API. Confirme os recursos do provedor com chamadas reais.", "Выберите шаблон и укажите API-ключ сервиса. Возможности провайдера требуют проверки реальными вызовами.", "テンプレートを選択して接続先のAPIキーを入力してください。ベンダーの機能は実際の呼び出しで確認が必要です。", "템플릿을 선택한 다음 업스트림 API 키를 입력하세요. 공급자 기능은 실제 호출로 확인해야 합니다."],
