  "ZIP 根目录使用 manifest.yaml；安装后先保持停用，启用时校验并发布快照。": ["Place manifest.yaml at the ZIP root. Installation is inactive; enabling validates and publishes a snapshot.", "Incluye manifest.yaml en la raíz del ZIP. La activación valida y publica una instantánea.", "Placez manifest.yaml à la racine du ZIP. L’activation valide et publie un instantané.", "manifest.yaml gehört in die ZIP-Wurzel. Erst die Aktivierung prüft und veröffentlicht den Snapshot.", "Coloque manifest.yaml na raiz do ZIP. A ativação valida e publica um estado.", "Поместите manifest.yaml в корень ZIP. Включение проверяет пакет и публикует снимок.", "ZIP直下にmanifest.yamlを置いてください。有効化時に検証してスナップショットを公開します。", "ZIP 루트에 manifest.yaml을 넣으세요. 활성화할 때 검증하고 스냅샷을 게시합니다."],
  "密钥只显示一次，保存哈希；模型、操作范围和额度由服务端执行。": ["Keys are shown once and stored as hashes. The server enforces model, operation and quota policies.", "Las claves se muestran una vez y se guardan como hashes. El servidor aplica permisos y cuotas.", "Les clés ne sont affichées qu’une fois et sont hachées. Le serveur applique les droits et quotas.", "Schlüssel werden einmal angezeigt und gehasht gespeichert. Der Server setzt Rechte und Limits durch.", "Chaves são exibidas uma vez e salvas como hashes. O servidor aplica permissões e cotas.", "Ключ показывается один раз и хранится как хеш. Сервер проверяет права и лимиты.", "キーは一度だけ表示しハッシュで保存します。権限と上限はサーバーで適用します。", "키는 한 번만 표시하고 해시로 저장합니다. 서버가 모델, 작업 권한과 한도를 적용합니다."],
  "创建密钥": ["Create key", "Crear clave", "Créer une clé", "Schlüssel erstellen", "Criar chave", "Создать ключ", "キーを作成", "키 생성"],
