  "0 表示不限制。启用 TPM 或预算前，请配置模型 token 硬上限和价格。": ["Zero means unlimited. TPM and budgets require model token bounds and deployment prices.", "Cero significa sin límite. TPM y presupuestos requieren límites de tokens y precios.", "Zéro signifie illimité. TPM et budgets exigent des limites de tokens et des tarifs.", "Null bedeutet unbegrenzt. TPM und Budgets benötigen Token-Grenzen und Preise.", "Zero significa sem limite. TPM e orçamento exigem limites de tokens e preços.", "Ноль означает отсутствие лимита. Для TPM и бюджета нужны пределы токенов и цены.", "0は無制限です。TPMと予算にはモデルのトークン上限と価格が必要です。", "0은 무제한입니다. TPM과 예산에는 모델 토큰 상한과 배포 가격이 필요합니다."],
  "请立即保存密钥": ["Save your key now", "Guarda la clave ahora", "Enregistrez votre clé", "Schlüssel jetzt sichern", "Salve sua chave agora", "Сохраните ключ сейчас", "今すぐキーを保存", "지금 키를 저장하세요"],
  "关闭后无法再次查看。": ["You cannot view it again after closing.", "No podrás verla al cerrar.", "Elle ne sera plus visible après fermeture.", "Nach dem Schließen nicht erneut sichtbar.", "Não será possível vê-la após fechar.", "После закрытия просмотр невозможен.", "閉じると再表示できません。", "닫은 후에는 다시 볼 수 없습니다."],
