  "已保存": ["Saved", "Guardado", "Enregistré", "Gespeichert", "Salvo", "Сохранено", "保存済み", "저장됨"],
  "登录管理控制台": ["Sign in to the admin console", "Inicia sesión en la consola", "Connectez-vous à la console", "Bei der Konsole anmelden", "Entre no console de administração", "Войти в консоль управления", "管理コンソールにログイン", "관리 콘솔에 로그인"],
  "登录": ["Sign in", "Iniciar sesión", "Connexion", "Anmelden", "Entrar", "Войти", "ログイン", "로그인"],
  "每次真实上游调用各记一条 Attempt，重试和失败费用分别保留。": ["Each upstream call has its own attempt. Retry usage and failure costs are retained separately.", "Cada llamada tiene un intento. El uso de reintentos y los costes de errores se guardan por separado.", "Chaque appel possède sa tentative. Usage des reprises et coûts d’échec sont conservés séparément.", "Jeder Aufruf ist ein Versuch. Nutzung bei Wiederholungen und Fehlerkosten bleiben getrennt.", "Cada chamada tem uma tentativa. Uso de novas tentativas e custos de falhas são preservados.", "Каждый вызов записан отдельно. Использование повторных попыток и затраты при сбоях сохраняются.", "上流呼び出しごとに試行を記録し、再試行の使用量と失敗時の費用も個別に保持します。", "업스트림 호출마다 시도를 기록하며 재시도 사용량과 실패 비용을 각각 보존합니다."],
  "时间": ["Time", "Hora", "Heure", "Zeit", "Hora", "Время", "時刻", "시간"],
  "公开模型": ["Public model", "Modelo público", "Modèle public", "Öffentliches Modell", "Modelo público", "Публичная модель", "公開モデル", "공개 모델"],
  "耗时": ["Latency", "Latencia", "Latence", "Latenz", "Latência", "Задержка", "所要時間", "소요 시간"],
  "下游使用稳定的公开模型名，Deployment 负责映射上游模型。": ["Clients use stable public names. Deployments map them to upstream models.", "Los clientes usan nombres estables. Los Deployments los asignan a modelos de origen.", "Les clients utilisent des noms stables. Les Deployments les associent aux modèles amont.", "Clients nutzen stabile Namen. Deployments ordnen diese den Upstream-Modellen zu.", "Clientes usam nomes estáveis. Deployments os mapeiam para modelos de origem.", "Клиенты используют стабильные имена. Deployments связывают их с внешними моделями.", "クライアントは安定した公開名を使い、Deploymentが上流モデルに対応付けます。", "클라이언트는 고정된 공개 이름을 사용하고 Deployment가 업스트림 모델에 연결합니다."],
  "搜索模型": ["Search models", "Buscar modelos", "Rechercher un modèle", "Modelle suchen", "Buscar modelos", "Поиск моделей", "モデルを検索", "모델 검색"],
