  "编辑能力": ["Edit capabilities", "Editar capacidades", "Modifier les capacités", "Fähigkeiten bearbeiten", "Editar capacidades", "Изменить возможности", "機能を編集", "기능 편집"],
  "停用": ["Disable", "Desactivar", "Désactiver", "Deaktivieren", "Desativar", "Отключить", "無効化", "비활성화"],
  "确认删除模型？请先移除对应 Deployment。": ["Delete this model? Remove its deployments first.", "¿Eliminar el modelo? Elimina primero sus Deployments.", "Supprimer ce modèle ? Retirez d’abord ses Deployments.", "Modell löschen? Zuerst seine Deployments entfernen.", "Excluir o modelo? Remova seus Deployments primeiro.", "Удалить модель? Сначала удалите её Deployments.", "モデルを削除しますか？先に対応するDeploymentを削除してください。", "모델을 삭제할까요? 먼저 연결된 Deployment를 제거하세요."],
  "在上游服务中发现并登记模型": ["Discover and register models from an upstream", "Descubre y registra modelos desde un servicio", "Découvrez et enregistrez des modèles depuis un service", "Modelle über einen Upstream suchen und registrieren", "Descubra e registre modelos de um serviço", "Найдите и зарегистрируйте модели внешнего сервиса", "接続先サービスでモデルを検出して登録してください", "업스트림 서비스에서 모델을 검색하고 등록하세요"],
  "仅声明已确认支持的能力": ["Declare only confirmed capabilities", "Declara solo capacidades confirmadas", "Déclarez uniquement les capacités confirmées", "Nur bestätigte Fähigkeiten deklarieren", "Declare apenas capacidades confirmadas", "Заявляйте только подтверждённые возможности", "確認済みの機能のみ宣言してください", "확인된 기능만 선언하세요"],
  "优先级降序选择，同层按权重分配；Router 统一控制重试。": ["Higher priority first, weighted within a tier. The Router owns retries.", "Mayor prioridad primero y reparto por peso. El Router controla los reintentos.", "Priorité décroissante, puis répartition pondérée. Le Router gère les reprises.", "Höchste Priorität zuerst, danach Gewichtung. Der Router steuert Wiederholungen.", "Maior prioridade primeiro e distribuição por peso. O Router controla as tentativas.", "Сначала больший приоритет, затем вес. Повторы контролирует Router.", "優先度の高い順に選び、同順位では重みで配分します。再試行はRouterが管理します。", "우선순위가 높은 순으로 선택하고 같은 단계에서는 가중치로 분배합니다. Router가 재시도를 관리합니다."],
  "添加 Deployment": ["Add deployment", "Añadir Deployment", "Ajouter un Deployment", "Deployment hinzufügen", "Adicionar Deployment", "Добавить Deployment", "Deploymentを追加", "Deployment 추가"],
  "上游模型": ["Upstream model", "Modelo de origen", "Modèle amont", "Upstream-Modell", "Modelo de origem", "Внешняя модель", "上流モデル", "업스트림 모델"],
