  "缓存价格 / 百万 token": ["Cached input / million tokens", "Caché / millón de tokens", "Cache / million de tokens", "Cache / Million Tokens", "Cache / milhão de tokens", "Кеш / миллион токенов", "キャッシュ / 100万トークン", "캐시 / 백만 토큰"],
  "运行策略实时发布；监听、认证和资源上限在 gateway.yaml 配置后重启。": ["Runtime policies publish immediately. Listener, authentication and resource settings in gateway.yaml require a restart.", "Las políticas se publican al instante. Red, autenticación y recursos en gateway.yaml requieren reinicio.", "Les stratégies sont publiées immédiatement. Réseau, authentification et ressources de gateway.yaml exigent un redémarrage.", "Laufzeitregeln gelten sofort. Netzwerk, Authentifizierung und Ressourcen in gateway.yaml benötigen einen Neustart.", "Políticas são publicadas imediatamente. Rede, autenticação e recursos em gateway.yaml exigem reinício.", "Политики публикуются сразу. Сеть, авторизация и ресурсы в gateway.yaml требуют перезапуска.", "実行ポリシーは即時公開されます。gateway.yamlの接続・認証・リソース設定には再起動が必要です。", "실행 정책은 즉시 게시됩니다. gateway.yaml의 네트워크, 인증 및 리소스 설정은 재시작이 필요합니다."],
