  "最高优先级系统提示词": ["Highest-priority system prompt", "Prompt de sistema prioritario", "Instruction système prioritaire", "Systemanweisung mit höchster Priorität", "Prompt de sistema prioritário", "Системная инструкция высшего приоритета", "最優先のシステムプロンプト", "최우선 시스템 프롬프트"],
