  "配置保存后发布新快照，在途请求继续使用原连接。": ["Saving publishes a new snapshot. In-flight requests retain their existing connections.", "Guardar publica una nueva instantánea. Las solicitudes en curso conservan sus conexiones.", "L’enregistrement publie un nouvel instantané. Les requêtes en cours conservent leurs connexions.", "Speichern veröffentlicht einen neuen Snapshot. Laufende Anfragen behalten ihre Verbindungen.", "Salvar publica um novo estado. Solicitações em andamento mantêm suas conexões.", "Сохранение публикует новый снимок. Текущие запросы сохраняют свои соединения.", "保存すると新しいスナップショットを公開し、処理中のリクエストは元の接続を使い続けます。", "저장하면 새 스냅샷이 게시됩니다. 처리 중인 요청은 기존 연결을 계속 사용합니다."],
