  "正文按日志上限留存；认证请求头不记录，凭据回显已脱敏。": ["Bodies are retained up to the log limit. Authentication headers are excluded and echoed credentials are redacted.", "Los cuerpos se conservan hasta el límite del registro. No se guardan cabeceras de autenticación y las credenciales devueltas se ocultan.", "Les corps sont conservés dans la limite du journal. Les en-têtes d’authentification sont exclus et les identifiants renvoyés sont masqués.", "Inhalte werden bis zum Protokolllimit gespeichert. Authentifizierungsheader werden ausgeschlossen und wiedergegebene Zugangsdaten entfernt.", "Os corpos são mantidos até o limite do registro. Cabeçalhos de autenticação são excluídos e credenciais retornadas são ocultadas.", "Содержимое сохраняется в пределах лимита журнала. Заголовки авторизации не записываются, возвращённые секреты скрываются.", "本文はログ上限まで保持します。認証ヘッダーは記録せず、応答中の認証情報は除去します。", "본문은 로그 한도까지 보관합니다. 인증 헤더는 기록하지 않으며 응답에 포함된 자격 증명은 제거합니다."]
